\t\t\t\tcontinue
\t\t\t}
\t\t\tfor i, expectedElem := range expected {
\t\t\t\ttestNumberObject(t, array.Elements[i], float64(expectedElem))
\t\t\t}
\t\tcase string:
\t\t\terrObj, ok := evaluated.(*object.Error)
\t\t\tif !ok {
\t\t\t\tt.Errorf("object is not Error for %q. got=%T (%+v)", tt.input, evaluated, evaluated)
\t\t\t\tcontinue
\t\t\t}
\t\t\tlogErrorWithPosition(t, errObj.Message, expected)
\t\t}
\t}
