func TestStringRangeAssignment(t *testing.T) {
\ttests := []struct {
\t\tinput    string
\t\texpected interface{}
\t}{
\t\t{`s="hello"; s[0]="H"; s`, "Hello"},
\t\t{`s="hello"; s[1:3]="EY"; s`, "hEYlo"},
\t\t{`s="hello"; s[2:5:2]="A"; s`, "heAlA"},
\t\t{`s="hello"; s[1:4]="X"; s`, "hXXXo"},
\t\t{`s="héllo"; s[1]="É"; s`, "hÉllo"},
\t\t{`s="héllo"; s[1:3]="X"; s`, "hXXlo"},
\t\t{`s="hello"; s[3:1]="x"`, "range assignment size mismatch: target=0 value=1"},
\t\t{`s="hello"; s[1:3]=5`, "range assignment expects STRING value, got NUMBER"},
\t\t{`s="hello"; s[0]="too long"`, "index assignment expects single-character STRING value, got 8 characters"},
\t\t{`s="hello"; s[1:3]="abcdef"`, "range assignment size mismatch: target=2 value=6"},
\t}

\tfor _, tt := range tests {
\t\tevaluated := testEval(tt.input)
\t\tswitch expected := tt.expected.(type) {
\t\tcase string:
\t\t\tif s, ok := evaluated.(*object.String); ok {
\t\t\t\tif s.Value != expected {
\t\t\t\t\tt.Errorf("result is not the right string for %q. got=%q, want=%q", tt.input, s.Value, expected)
\t\t\t\t}
\t\t\t\tcontinue
\t\t\t}
\t\t\tif errObj, ok := evaluated.(*object.Error); ok {
\t\t\t\tlogErrorWithPosition(t, errObj.Message, expected)
\t\t\t\tcontinue
\t\t\t}
\t\t\tt.Errorf("object is not the right result for %q. got=%T (%+v)", tt.input, evaluated, evaluated)
\t\t}
\t}
}

'''
